
CREATE TABLE "QUICKSQLORDER" ("ID" INT IDENTITY(1,1) NOT NULL, "CUSTOMERNAME" VARCHAR(64) NULL, "CUSTOMERID" INT NOT NULL, "AMOUNT" NUMERIC(18,4) NOT NULL, "STATE" INT NOT NULL, "CREATEDAT" DATETIME(3) NOT NULL, "PAIDAT" DATETIME(3) NULL, "NOTE" CLOB NULL, CONSTRAINT "PK_QUICKSQLORDER" PRIMARY KEY ("ID")) ; CREATE INDEX "IX_QUICKSQLORDER_CREATEDAT" ON "QUICKSQLORDER" ( "CREATEDAT" ASC )
